insert into punts_observacio
  (slug, nom, municipi, descripcio, altitud, horitzo_obert, accessibilitat, origen, estat, ubicacio)
values
  ('centre-observacio-univers', 'Centre d''Observació de l''Univers', 'Àger', 'Equipament del Parc Astronòmic del Montsec, al vessant sud de la serra. El Montsec és Reserva i Destinació Turística Starlight i té un dels cels més foscos de Catalunya.', 817, array['SE', 'S', 'SW']::text[], 'Accés en cotxe fins a l''equipament', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[0.73684,42.024603]}'), 4326)::geography),
  ('port-d-ager', 'Port d''Àger', 'Àger', 'Coll de la carretera C-12 que dona entrada a la vall d''Àger. Bon punt d''aturada a la zona protegida del Montsec, lluny de nuclis grans.', 904, null, 'Accés en cotxe per la C-12', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[0.750598,41.978823]}'), 4326)::geography),
  ('prades', 'Prades', 'Prades', 'Vila a l''altiplà de les Muntanyes de Prades, Reserva Starlight juntament amb la serra de Montsant. Seu del Parc Astronòmic Muntanyes de Prades; cal allunyar-se del nucli per evitar l''enllumenat.', 955, null, 'Accés en cotxe', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[0.987925,41.309622]}'), 4326)::geography),
  ('la-mussara', 'la Mussara', 'Vilaplana', 'Poble abandonat al caire dels cingles de la serra de la Mussara, amb vista oberta cap al Camp de Tarragona. El cel és fosc cap al nord, però cap al sud es veu la llum de l''àrea urbana.', 981, array['SE', 'S', 'SW']::text[], 'Accés en cotxe per la carretera de la Mussara', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[1.027593,41.252322]}'), 4326)::geography),
  ('siurana', 'Siurana', 'Cornudella de Montsant', 'Nucli enfilat en un esperó rocós sobre el pantà de Siurana, a tocar de la serra de Montsant. Poca contaminació lumínica i horitzó obert cap al sud-oest.', 726, array['S', 'SW', 'W']::text[], 'Accés en cotxe', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[0.931753,41.25776]}'), 4326)::geography),
  ('la-morera-de-montsant', 'la Morera de Montsant', 'la Morera de Montsant', 'Poble al peu dels cingles de la serra de Montsant, dins la Reserva Starlight. Els cingles tapen el nord; cap al sud la vista s''obre sobre el Priorat.', 749, array['SE', 'S', 'SW']::text[], 'Accés en cotxe', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[0.841819,41.264958]}'), 4326)::geography),
  ('montgai', 'Montgai', 'Montgai', 'Municipi de la Noguera amb certificació de Destinació Turística Starlight. Terreny planer amb poques llums al voltant.', 288, null, 'Accés en cotxe', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[0.961008,41.79986]}'), 4326)::geography),
  ('observatori-castelltallat', 'Observatori Astronòmic de Castelltallat', 'Sant Mateu de Bages', 'Observatori d''aficionats a la serra de Castelltallat, al Bages. Punt alt i allunyat de les poblacions de la comarca.', 873, null, 'Accés en cotxe fins a l''observatori', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[1.632295,41.793829]}'), 4326)::geography),
  ('observatori-pujalt', 'Observatori de Pujalt', 'Pujalt', 'Observatori astronòmic al poble de Pujalt, a l''Alta Anoia, en un turó amb el cel de la Catalunya central.', 747, null, 'Accés en cotxe', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[1.424336,41.717134]}'), 4326)::geography),
  ('santa-fe-del-montseny', 'Santa Fe del Montseny', 'Fogars de Montclús', 'Clot al cor del Montseny envoltat de fagedes. Cel fosc al zenit, però l''horitzó queda tapat pels cims del voltant.', 1131, null, 'Accés en cotxe per la BV-5114', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[2.464282,41.774127]}'), 4326)::geography),
  ('collformic', 'Collformic', 'el Brull', 'Coll del Montseny entre Osona i el Vallès, amb aparcament. Accessible i amb vista a la plana de Vic, que aporta llum cap a l''oest.', 1129, null, 'Accés en cotxe per la BV-5114', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[2.347393,41.800879]}'), 4326)::geography),
  ('coll-de-pal', 'Coll de Pal', 'Bagà', 'Coll d''alta muntanya al Parc Natural del Cadí-Moixeró, per sobre dels 2.000 m. Cel molt fosc i aire sec; carretera de muntanya que pot tenir neu a l''hivern.', 2099, array['N', 'S']::text[], 'Accés en cotxe per la BV-4024', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[1.922542,42.30384]}'), 4326)::geography),
  ('rasos-de-peguera', 'Rasos de Peguera', 'Fígols', 'Altiplà d''alta muntanya al nord del Berguedà. Vista oberta cap al sud sobre la Catalunya central.', 1786, array['SE', 'S', 'SW']::text[], 'Accés en cotxe per la carretera dels Rasos', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[1.776223,42.153348]}'), 4326)::geography),
  ('port-del-comte', 'el Port del Comte', 'la Coma i la Pedra', 'Zona de l''estació d''esquí del Port del Comte, al Solsonès. Alçada elevada i poques llums a prop fora de temporada.', 1650, null, 'Accés en cotxe fins a l''estació d''esquí', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[1.568945,42.173757]}'), 4326)::geography),
  ('bellmunt', 'Santuari de Bellmunt', 'Sant Pere de Torelló', 'Santuari al cim de Bellmunt, sobre la plana de Vic. Panoràmica de 360°; la llum d''Osona es nota cap al sud.', 1221, array['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW']::text[], 'Accés en cotxe fins al santuari', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[2.293716,42.101498]}'), 4326)::geography),
  ('coll-d-ares', 'Coll d''Ares', 'Molló', 'Coll fronterer del Ripollès, lluny de grans poblacions. Vista oberta cap al Vallespir i cap a la vall de Camprodon.', 1515, array['N', 'S']::text[], 'Accés en cotxe per la C-38', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[2.456666,42.366888]}'), 4326)::geography),
  ('vallter-2000', 'Vallter 2000', 'Setcases', 'Circ glacial a la capçalera del Ter, per sobre dels 2.000 m. Cel molt fosc; les carenes tanquen el nord i l''oest.', 2163, array['SE', 'S']::text[], 'Accés en cotxe per la GIV-5264', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[2.265045,42.426932]}'), 4326)::geography),
  ('mont-caro', 'Mont Caro', 'Roquetes', 'Sostre del massís dels Ports, amb vista de 360° sobre el delta de l''Ebre i el Matarranya. Lluny de nuclis grans, amb el cel fosc dels Ports.', 1407, array['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW']::text[], 'Carretera asfaltada des de Roquetes; comprovar l''accés fins al cim', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[0.34311,40.80313]}'), 4326)::geography),
  ('platja-del-trabucador', 'Platja del Trabucador', 'la Ràpita', 'Barra de sorra del delta de l''Ebre amb mar a banda i banda. Horitzó pla i net, ideal per a sortides i postes d''astres arran d''aigua.', 0, array['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW']::text[], 'Accés en cotxe fins a l''inici de la barra', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[0.701111,40.580332]}'), 4326)::geography),
  ('el-cortalet', 'el Cortalet (Aiguamolls de l''Empordà)', 'Castelló d''Empúries', 'Centre del Parc Natural dels Aiguamolls de l''Empordà. Terreny pla i obert cap al golf de Roses; la costa aporta llum en temporada alta.', 3, array['E', 'SE', 'S']::text[], 'Accés en cotxe fins al centre d''informació', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[3.092703,42.224568]}'), 4326)::geography),
  ('cap-de-creus', 'Cap de Creus', 'Cadaqués', 'Punta més oriental de la península, al Parc Natural del Cap de Creus. Horitzó de mar molt ampli cap a l''est, bo per a sortides de la Lluna i del Sol.', 74, array['N', 'NE', 'E', 'SE', 'S']::text[], 'Accés en cotxe fins al far', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[3.315867,42.318913]}'), 4326)::geography),
  ('port-de-la-bonaigua', 'Port de la Bonaigua', 'Alt Àneu', 'Port de muntanya a més de 2.000 m entre el Pallars Sobirà i la Val d''Aran. Cel d''alta muntanya; la carretera pot tancar per neu.', 2066, null, 'Accés en cotxe per la C-28', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[0.978152,42.664089]}'), 4326)::geography),
  ('coll-de-comiols', 'Coll de Comiols', 'Artesa de Segre', 'Coll entre la Noguera i el Pallars Jussà, en una zona molt poc poblada al nord-est del Montsec.', 1104, null, 'Accés en cotxe', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[1.090466,42.05443]}'), 4326)::geography),
  ('santuari-del-miracle', 'Santuari del Miracle', 'Riner', 'Santuari del Solsonès en un altiplà agrícola amb poques llums, a la Catalunya central.', 826, null, 'Accés en cotxe fins al santuari', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[1.525131,41.914867]}'), 4326)::geography),
  ('collada-de-toses', 'Collada de Toses', 'Alp', 'Coll de la N-260 entre el Ripollès i la Cerdanya, a uns 1.800 m. Accessible tot l''any, amb aparcaments a la vora.', 1772, null, 'Accés en cotxe per la N-260', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[1.984746,42.331562]}'), 4326)::geography),
  ('santuari-del-far', 'Santuari del Far', 'Susqueda', 'Santuari al caire d''un cingle de les Guilleries, amb vista cap a l''est sobre la Selva. Cel fosc cap a l''oest, cap al massís.', 1119, array['E', 'SE', 'S']::text[], 'Accés en cotxe fins al santuari', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[2.535876,42.02156]}'), 4326)::geography),
  ('pla-de-beret', 'Plan de Beret', 'Naut Aran', 'Altiplà d''alta muntanya a la Val d''Aran, a prop de les fonts de la Garona i la Noguera Pallaresa. Espai ample i obert, molt fosc fora de temporada d''esquí.', 1843, null, 'Accés en cotxe per la carretera de Beret', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[0.963968,42.723151]}'), 4326)::geography),
  ('panta-de-cavallers', 'Pantà de Cavallers', 'la Vall de Boí', 'Embassament d''alta muntanya a la porta del Parc Nacional d''Aigüestortes i Estany de Sant Maurici, Reserva Starlight. Cel molt fosc; les muntanyes limiten l''horitzó.', 1756, null, 'Accés en cotxe fins a la presa', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[0.856611,42.589489]}'), 4326)::geography),
  ('coll-del-moro', 'Coll del Moro', 'Gandesa', 'Turó de la Terra Alta amb un poblat ibèric al cim i vista de 360° sobre la comarca, molt poc poblada.', 476, array['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW']::text[], 'Accés en cotxe fins al poblat ibèric', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[0.385835,41.049204]}'), 4326)::geography),
  ('mirador-coll-de-boixols', 'Mirador del Coll de Bóixols', 'Coll de Nargó', 'Mirador al coll de Bóixols, entre l''Alt Urgell i el Pallars Jussà, en una de les zones més despoblades de Catalunya.', 1339, null, 'Accés en cotxe per la L-511', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[1.185322,42.16946]}'), 4326)::geography),
  ('mare-de-deu-del-mont', 'Santuari de la Mare de Déu del Mont', 'Albanyà', 'Santuari al cim del Mont, entre la Garrotxa i l''Alt Empordà, amb panoràmica de 360° del Pirineu al mar.', 1099, array['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW']::text[], 'Accés en cotxe per una carretera estreta des de Beuda', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[2.707218,42.258408]}'), 4326)::geography),
  ('sant-joan-de-l-erm', 'Sant Joan de l''Erm', 'Montferrer i Castellbò', 'Clariana en un bosc de l''Alt Urgell, a tocar del Parc Natural de l''Alt Pirineu. Molt lluny de qualsevol nucli gran.', 1732, null, 'Pista forestal des de Castellbò', 'OFICIAL', 'PUBLICAT', st_setsrid(st_geomfromgeojson('{"type":"Point","coordinates":[1.287677,42.415105]}'), 4326)::geography)
